-- Cast on the column: the index on created_at cannot be used
CREATE INDEX events_time_idx ON events (created_at);
EXPLAIN (COSTS OFF)
SELECT count(*) FROM events WHERE created_at::date = '2026-01-15';
-- A range on the bare column: the index is used
-- result: A condition the index can serve is called "sargable". Keep the column alone on one side of the comparison.
CREATE INDEX events_time_idx ON events (created_at);
EXPLAIN (COSTS OFF)
SELECT count(*) FROM events WHERE created_at >= '2026-01-15' AND created_at < '2026-01-16';

-- OFFSET 60000: look at "actual rows" on the index scan
CREATE INDEX events_feed_idx ON events (created_at DESC, id DESC);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT id, kind, created_at FROM events ORDER BY created_at DESC, id DESC LIMIT 20 OFFSET 60000;
-- Keyset: "give me 20 rows after the last one I saw"
-- result: The client sends back the (created_at, id) of the last row it received. The scan starts there and reads 20 rows.
CREATE INDEX events_feed_idx ON events (created_at DESC, id DESC);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT id, kind, created_at FROM events
WHERE (created_at, id) < (TIMESTAMP '2026-01-24 03:20:00', 40000)
ORDER BY created_at DESC, id DESC LIMIT 20;

