CREATE TABLE price_audit (
  product_id integer, old_price integer, new_price integer,
  changed_by text DEFAULT current_user, changed_at timestamptz DEFAULT now()
);
CREATE FUNCTION log_price_change() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO price_audit (product_id, old_price, new_price) VALUES (OLD.id, OLD.price, NEW.price);
  RETURN NULL;
END $$;
CREATE TRIGGER products_price_audit AFTER UPDATE OF price ON products
  FOR EACH ROW WHEN (OLD.price IS DISTINCT FROM NEW.price)
  EXECUTE FUNCTION log_price_change();

